   208	    private Map<String, Object> reservationToJson(Reservation reservation) {
   209	        Map<String, Object> map = new java.util.LinkedHashMap<>();
   210	        map.put("id", reservation.getId());
   211	        map.put("roomNumber", reservation.getRoomNumber());
   212	        map.put("guestName", reservation.getGuestName());
   213	        map.put("guestEmail", reservation.getGuestEmail());
   214	        map.put("guestCpf", reservation.getGuestCpf());
   215	        map.put("checkIn", DateFormatter.toISO(reservation.getCheckIn()));
   216	        map.put("checkOut", DateFormatter.toISO(reservation.getCheckOut()));
   217	        map.put("guests", reservation.getGuests());
   218	        map.put("ratePlan", reservation.getRatePlan().name());
   219	        map.put("nights", reservation.getNights());
   220	        map.put("subtotal", reservation.getSubtotal());
   221	        map.put("discount", reservation.getDiscount());
   222	        map.put("total", reservation.getTotal());
   223	        map.put("status", reservation.getStatus().name());
   224	        map.put("amountPaid", reservation.getAmountPaid());
   225	        map.put("refund", reservation.getRefund());
   226	        return map;
   227	    }
