   229	    private void handleReservationError(io.javalin.http.Context ctx, String message) {
   230	        if (message.contains("Room not found")) {
   231	            ctx.status(404).json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
   232	        } else if (message.contains("Invalid guest count")) {
   233	            ctx.status(422).json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Invalid guest count"));
   234	        } else if (message.contains("Invalid dates")) {
   235	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid dates"));
   236	        } else if (message.contains("Room unavailable")) {
   237	            ctx.status(409).json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room unavailable"));
   238	        } else {
   239	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", message));
   240	        }
   241	    }
   242	}
