     1	package com.pousada.marealta.service;
     2	
     3	import com.pousada.marealta.domain.RatePlan;
     4	import com.pousada.marealta.util.MoneyRounder;
     5	import com.pousada.marealta.util.SeasonCalculator;
     6	
     7	import java.time.LocalDate;
     8	
     9	public class PriceCalculator {
    10	    public static class PriceBreakdown {
    11	        public final int nights;
    12	        public final double subtotal;
    13	        public final double discount;
    14	        public final double total;
    15	
    16	        public PriceBreakdown(int nights, double subtotal, double discount, double total) {
    17	            this.nights = nights;
    18	            this.subtotal = subtotal;
    19	            this.discount = discount;
    20	            this.total = total;
    21	        }
    22	    }
    23	
    24	    public static PriceBreakdown calculate(double baseNightlyRate, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    25	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    26	
    27	        double subtotal = 0.0;
    28	        for (int i = 0; i < nights; i++) {
    29	            LocalDate nightDate = checkIn.plusDays(i);
    30	            double nightlyRate = SeasonCalculator.getNightlyRate(baseNightlyRate, nightDate);
    31	            nightlyRate = MoneyRounder.round(nightlyRate);
    32	            subtotal += nightlyRate;
    33	        }
    34	        subtotal = MoneyRounder.round(subtotal);
    35	
    36	        double discount = 0.0;
    37	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    38	            discount = subtotal * ratePlan.getDiscountRate();
    39	            discount = MoneyRounder.round(discount);
    40	        }
    41	
    42	        double total = subtotal - discount;
    43	        total = MoneyRounder.round(total);
    44	
    45	        return new PriceBreakdown(nights, subtotal, discount, total);
    46	    }
    47	}
