    44	
    45	        StringBuilder csv = new StringBuilder();
    46	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    47	
    48	        double totalAmount = 0;
    49	        for (Reservation res : reservations) {
    50	            csv.append(res.getId()).append(",");
    51	            csv.append(res.getRoomNumber()).append(",");
    52	            csv.append(DateFormatter.toISO(res.getCheckIn())).append(",");
