    54	            csv.append(res.getStatus().name()).append(",");
    55	
    56	            double amount = res.getAmountPaid();
    57	            if (res.getRefund() != null) {
    58	                amount -= res.getRefund();
    59	            }
    60	
    61	            csv.append(MoneyFormatter.formatForCSV(amount)).append("\n");
    62	            totalAmount += amount;
    63	        }
    64	
    65	        csv.append("total,,,,,").append(MoneyFormatter.formatForCSV(totalAmount)).append("\n");
    66	
    67	        return csv.toString();
    68	    }
