     8	import java.util.ArrayList;
     9	import java.util.List;
    10	
    11	public class MessageSender {
    12	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
    13	    private static final String ARCHIVE_PREFIX = "[Cópia] ";
    14	
    15	    private final MessageRepository messageRepository;
    16	    private final List<MessagePolicy> policies;
    17	    private final boolean testModeEnabled;
    18	
    19	    public MessageSender(MessageRepository messageRepository, boolean testModeEnabled) {
    20	        this.messageRepository = messageRepository;
    21	        this.testModeEnabled = testModeEnabled;
    22	        this.policies = new ArrayList<>();
    23	
    24	        this.policies.add(new EmailValidationPolicy());
    25	        this.policies.add(new TestModePolicy(testModeEnabled));
    26	    }
    27	
    28	    public void send(String originalRecipient, String subject, String body) throws Exception {
    29	        MessageContext context = new MessageContext(originalRecipient, subject, body);
    30	
    31	        MessagePolicyResult result = applyPolicies(context);
    32	
    33	        MessageStatus status = result.blocked ? MessageStatus.BLOCKED : MessageStatus.SENT;
    34	        Message message = new Message(0, MessageChannel.EMAIL, result.recipient, result.subject, result.body, status);
    35	
    36	        messageRepository.save(message);
    37	
    38	        if (!result.blocked && !testModeEnabled) {
    39	            sendArchiveCopy(result.recipient, result.subject, result.body);
    40	        }
    41	    }
    42	
    43	    private MessagePolicyResult applyPolicies(MessageContext context) {
    44	        MessagePolicyResult result = MessagePolicyResult.pass(context.originalRecipient, context.originalSubject, context.originalBody);
    45	        for (MessagePolicy policy : policies) {
    46	            result = policy.apply(new MessageContext(result.recipient, result.subject, result.body));
    47	            if (result.blocked) {
    48	                return result;
    49	            }
    50	        }
    51	        return result;
    52	    }
    53	
    54	    private void sendArchiveCopy(String originalRecipient, String subject, String body) throws Exception {
    55	        String archiveSubject = ARCHIVE_PREFIX + subject;
    56	        Message archiveMessage = new Message(0, MessageChannel.EMAIL, ARCHIVE_EMAIL, archiveSubject, body, MessageStatus.SENT);
    57	        messageRepository.save(archiveMessage);
    58	    }
    59	
    60	    public void addPolicy(MessagePolicy policy) {
    61	        policies.add(policy);
    62	    }
    63	}
