     6	public class SeasonCalculator {
     7	    public static boolean isHighSeason(LocalDate date) {
     8	        Month month = date.getMonth();
     9	        int day = date.getDayOfMonth();
    10	
    11	        if (month == Month.JULY) {
    12	            return true;
    13	        }
    14	
    15	        if (month == Month.DECEMBER && day >= 15) {
    16	            return true;
    17	        }
    18	
    19	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    20	            return true;
    21	        }
    22	
    23	        return false;
    24	    }
    25	
    26	    public static double getNightlyRate(double baseRate, LocalDate date) {
    27	        if (isHighSeason(date)) {
    28	            return baseRate * 1.20;
    29	        }
    30	        return baseRate;
    31	    }
    32	}

