     8	        Month month = date.getMonth();
     9	        int day = date.getDayOfMonth();
    10	
    11	        if (month == Month.JULY) {
    12	            return true;
    13	        }
    14	
    15	        if (month == Month.DECEMBER && day >= 15) {
    16	            return true;
    17	        }
    18	
    19	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    20	            return true;
    21	        }
    22	
    23	        return false;
    24	    }
    25	
